// Project folders on disk: <data>/projects/<user id>/<project id>/. Both ids are generated by the hub and checked
// against ID_PATTERN before they become a path; a project's name is a label in the store and never touches the disk.
import { lstat, mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises"
import { dirname, join, relative, sep } from "node:path"
import { resolveInRoot } from "../core/workspace.js"
import { ID_PATTERN } from "./secrets.js"
import { ZipWriter, type ZipEntry } from "./zip.js"

/** Leftovers of an interrupted atomic write (`writeFileAtomic`): `<name>.<pid>.<hex>.tmp`. Never part of a download. */
const ATOMIC_LEFTOVER = /\.\d+\.[0-9a-f]{8}\.tmp$/

function checkId(id: string): string {
  if (!ID_PATTERN.test(id)) throw new Error("Not a generated id")
  return id
}

export interface ProjectFile {
  /** Relative path, "/" between folders. */
  name: string
  path: string
  size: number
  modified: Date
}

export class ProjectFiles {
  readonly root: string

  constructor(dataDir: string) {
    this.root = join(dataDir, "projects")
  }

  userDir(userId: string): string {
    return join(this.root, checkId(userId))
  }

  projectDir(userId: string, projectId: string): string {
    return join(this.userDir(userId), checkId(projectId))
  }

  async create(userId: string, projectId: string): Promise<string> {
    const dir = this.projectDir(userId, projectId)
    await mkdir(dir, { recursive: true, mode: 0o700 })
    return dir
  }

  async remove(userId: string, projectId: string): Promise<void> {
    await rm(this.projectDir(userId, projectId), { recursive: true, force: true })
  }

  async removeUser(userId: string): Promise<void> {
    await rm(this.userDir(userId), { recursive: true, force: true })
  }

  /** The regular files under a folder; links and special files are skipped, never followed. */
  async list(dir: string): Promise<ProjectFile[]> {
    const found: ProjectFile[] = []
    const walk = async (folder: string): Promise<void> => {
      let names: string[]
      try {
        names = await readdir(folder)
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT") return
        throw error
      }
      for (const name of names.sort()) {
        const path = join(folder, name)
        const info = await lstat(path)
        if (info.isDirectory()) await walk(path)
        else if (info.isFile()) found.push({ name: relative(dir, path).split(sep).join("/"), path, size: info.size, modified: info.mtime })
      }
    }
    await walk(dir)
    return found
  }

  /** Bytes the user's projects take on disk (regular files). */
  async usage(userId: string): Promise<number> {
    return (await this.list(this.userDir(userId))).reduce((sum, file) => sum + file.size, 0)
  }

  /** Streams the project as a zip; leftover temporary files of interrupted writes are left out. */
  async download(userId: string, projectId: string, write: (chunk: Buffer) => Promise<void>): Promise<void> {
    const zip = new ZipWriter(write)
    for (const file of await this.list(this.projectDir(userId, projectId))) {
      if (ATOMIC_LEFTOVER.test(file.name)) continue
      await zip.add(file.name, await readFile(file.path), file.modified)
    }
    await zip.finish()
  }

  /** Writes checked archive entries into a NEW, empty project folder, each through the core's in-root check. */
  async unpack(userId: string, projectId: string, entries: readonly ZipEntry[]): Promise<void> {
    const dir = await this.create(userId, projectId)
    for (const entry of entries) {
      const path = resolveInRoot(dir, entry.name)
      await mkdir(dirname(path), { recursive: true, mode: 0o700 })
      // "wx": an existing file (or a link planted by an earlier entry) is never written through.
      await writeFile(path, entry.data, { flag: "wx", mode: 0o600 })
    }
  }
}
